// withHistory adds the history hooks to the appropriate schemas - generated by enthistory
func (c *Client) WithHistory() {
	if !c.historyActivated {

		// AgentDefinition hooks
		c.AgentDefinition.Use(enthistory.HistoryTriggerInsert[*AgentDefinitionMutation]())
		c.AgentDefinition.Use(enthistory.HistoryTriggerUpdate[*AgentDefinitionMutation]())
		c.AgentDefinition.Use(enthistory.HistoryTriggerDelete[*AgentDefinitionMutation]())

		// LLMUsage hooks
		c.LLMUsage.Use(enthistory.HistoryTriggerInsert[*LLMUsageMutation]())
		c.LLMUsage.Use(enthistory.HistoryTriggerUpdate[*LLMUsageMutation]())
		c.LLMUsage.Use(enthistory.HistoryTriggerDelete[*LLMUsageMutation]())

		// MCPConnection hooks
		c.MCPConnection.Use(enthistory.HistoryTriggerInsert[*MCPConnectionMutation]())
		c.MCPConnection.Use(enthistory.HistoryTriggerUpdate[*MCPConnectionMutation]())
		c.MCPConnection.Use(enthistory.HistoryTriggerDelete[*MCPConnectionMutation]())

		// OAuthConnection hooks
		c.OAuthConnection.Use(enthistory.HistoryTriggerInsert[*OAuthConnectionMutation]())
		c.OAuthConnection.Use(enthistory.HistoryTriggerUpdate[*OAuthConnectionMutation]())
		c.OAuthConnection.Use(enthistory.HistoryTriggerDelete[*OAuthConnectionMutation]())

		// Subscription hooks
		c.Subscription.Use(enthistory.HistoryTriggerInsert[*SubscriptionMutation]())
		c.Subscription.Use(enthistory.HistoryTriggerUpdate[*SubscriptionMutation]())
		c.Subscription.Use(enthistory.HistoryTriggerDelete[*SubscriptionMutation]())

		// User hooks
		c.User.Use(enthistory.HistoryTriggerInsert[*UserMutation]())
		c.User.Use(enthistory.HistoryTriggerUpdate[*UserMutation]())
		c.User.Use(enthistory.HistoryTriggerDelete[*UserMutation]())

		c.historyActivated = true
	}
}

type (
	// config is the configuration for the client and its builder.
	config struct {
		// driver used for executing database requests.
		driver dialect.Driver
		// debug enable a debug logging.
		debug bool
		// log used for logging on debug mode.
		log func(...any)
		// hooks to execute on mutations.
		hooks *hooks
		// interceptors to execute on queries.
		inters *inters
	}
	// Option function to configure the client.
	Option func(*config)
)

// newConfig creates a new config for the client.
func newConfig(opts ...Option) config {
	cfg := config{log: log.Println, hooks: &hooks{}, inters: &inters{}}
	cfg.options(opts...)
	return cfg
}

// options applies the options on the config object.
func (c *config) options(opts ...Option) {
	for _, opt := range opts {
		opt(c)
	}
	if c.debug {
		c.driver = dialect.Debug(c.driver, c.log)
	}
}

// Debug enables debug logging on the ent.Driver.
func Debug() Option {
	return func(c *config) {
		c.debug = true
	}
}

// Log sets the logging function for debug mode.
func Log(fn func(...any)) Option {
	return func(c *config) {
		c.log = fn
	}
}

// Driver configures the client driver.
func Driver(driver dialect.Driver) Option {
	return func(c *config) {
		c.driver = driver
	}
}

// Open opens a database/sql.DB specified by the driver name and
// the data source name, and returns a new client attached to it.
// Optional parameters can be added for configuring the client.
func Open(driverName, dataSourceName string, options ...Option) (*Client, error) {
	switch driverName {
	case dialect.MySQL, dialect.Postgres, dialect.SQLite:
		drv, err := sql.Open(driverName, dataSourceName)
		if err != nil {
			return nil, err
		}
		return NewClient(append(options, Driver(drv))...), nil
	default:
		return nil, fmt.Errorf("unsupported driver: %q", driverName)
	}
}

